-- Name: generate_tracking_number(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_tracking_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.tracking_number :=
        'CS-' ||
        EXTRACT(YEAR FROM CURRENT_DATE)::TEXT ||
        '-' ||
        LPAD(nextval('tracking_number_seq')::TEXT, 5, '0');
    RETURN NEW;
END;
$$;


